"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["24720"],{529156(n){n.exports=JSON.parse('{"id":11895,"title":"PRD5\uFF1A\u89D2\u8272\u4E0E\u6743\u9650\u8FB9\u754C\u4E13\u5C5E\u63D0\u793A\u8BCD","description":"# \u6838\u5FC3\u4EFB\u52A1\\n\u8BF7\u4E3A\u5F53\u524D PRD \u6A21\u5757\u751F\u6210\u3010\u89D2\u8272\u4E0E\u6743\u9650\u8FB9\u754C\u3011\u8BF4\u660E\u3002\u8BF7\u4E25\u683C\u9075\u5FAA\u201C\u4E2D\u9897\u7C92\u5EA6\uFF08\u9875\u9762\u7EA7\u63A7\u5236 + \u6570\u636E\u884C\u7EA7\u9694\u79BB\uFF09\u201D\u7684\u67B6\u6784\u6807\u51C6\uFF0C\u4E0D\u8981\u5411\u4E0B\u94BB\u53D6\u5230\u6309\u94AE\u7EA7\u6216\u5B57\u6BB5\u7EA7\u7684\u6743\u9650\u63A7\u5236\u3002\\n\\n# \u8F93\u51FA\u89C4\u8303\\n\u8BF7\u8F93\u51FA\u4E00\u4E2A\u7ED3\u6784\u6E05\u6670\u7684 Markdown \u6743\u9650\u77E9\u9635\u8868\uFF0C\u5FC5\u987B\u5305\u542B\u4EE5\u4E0B\u6838\u5FC3\u7EF4\u5EA6\uFF0C\u4EE5\u4FBF\u4E8E IT \u90E8\u95E8\u8FDB\u884C RBAC \u548C\u6570\u636E\u6743\u9650\u89C6\u56FE\u7684\u5E95\u5C42\u8BBE\u8BA1\uFF1A\\n\\n1. **\u89D2\u8272\u540D\u79F0**\uFF1A\u6D89\u53CA\u8BE5\u6A21\u5757\u64CD\u4F5C\u7684\u4E1A\u52A1\u89D2\u8272\uFF08\u5982\uFF1A\u4E13\u5458\u3001\u4E3B\u7BA1\u3001\u8D22\u52A1\u7B49\uFF09\u3002\\n2. **\u9875\u9762/\u6A21\u5757\u8BBF\u95EE\u6743**\uFF1A\u5B9A\u4E49\u8BE5\u89D2\u8272\u5728\u524D\u7AEF\u5BFC\u822A\u83DC\u5355\u4E2D\u662F\u5426\u6709\u6743\u770B\u5230\u53CA\u8FDB\u5165\u8BE5\u6A21\u5757\u3002\\n3. **\u6570\u636E\u884C\u7EA7\u53EF\u89C1\u8303\u56F4\uFF08\u6838\u5FC3\u8FB9\u754C\uFF09**\uFF1A\u660E\u786E\u754C\u5B9A\u8BE5\u89D2\u8272\u5728\u9875\u9762\u5217\u8868\u4E2D\u80FD\u591F\u5237\u51FA\u54EA\u4E9B\u5E95\u5C42\u6570\u636E\u3002\u5FC5\u987B\u4F7F\u7528\u4E25\u8C28\u7684\u8FC7\u6EE4\u6761\u4EF6\u8BED\u8A00\uFF08\u4F8B\u5982\uFF1A\u201C\u4EC5\u53EF\u89C1\u6307\u6D3E\u4EBA\u662F\u81EA\u5DF1\u7684\u5355\u636E\u201D\u3001\u201C\u53EF\u89C1\u672C\u90E8\u95E8\u5185\u4EA7\u751F\u7684\u6240\u6709\u5355\u636E\u201D\u3001\u201C\u5168\u5C40\u5168\u91CF\u53EF\u89C1\u201D\uFF09\u3002\\n4. **\u57FA\u7840\u6570\u636E\u64CD\u4F5C\u6743**\uFF1A\u8BE5\u89D2\u8272\u5BF9\u4E0A\u8FF0\u53EF\u89C1\u8303\u56F4\u7684\u6570\u636E\uFF0C\u9ED8\u8BA4\u62E5\u6709\u7684\u6700\u9AD8\u64CD\u4F5C\u7C7B\u578B\uFF08\u5982\uFF1A\u67E5\u770B\u3001\u7F16\u8F91\u3001\u6D41\u8F6C\u3001\u5BA1\u6279\u3001\u4F5C\u5E9F\uFF09\u3002\\n\\n# \u8F93\u5165\u4FE1\u606F\\n- \u5F53\u524D\u6A21\u5757\u540D\u79F0\uFF1A[\u586B\u5199\u6A21\u5757\u540D\u79F0\uFF0C\u5982\uFF1A\u91C7\u8D2D\u8BE2\u4EF7\u4EFB\u52A1\u6C60 / \u90E8\u95E8\u7EE9\u6548 SLA \u770B\u677F]\\n- \u6D89\u53CA\u7684\u6838\u5FC3\u89D2\u8272\u7C7B\u578B\uFF1A[\u7B80\u8FF0\u76F8\u5173\u89D2\u8272\uFF0C\u5982\uFF1A\u5E95\u5C42\u4E13\u5458\u4E0E\u4E0A\u5C42\u90E8\u95E8\u4E3B\u7BA1]\\n\\n# \u793A\u4F8B\u53C2\u8003\u7ED3\u6784 (\u8BF7\u4E25\u683C\u5957\u7528\u6B64\u8868\u5934)\uFF1A\\n| \u89D2\u8272\u540D\u79F0 | \u9875\u9762/\u6A21\u5757\u8BBF\u95EE\u6743 | \u6570\u636E\u884C\u7EA7\u53EF\u89C1\u8303\u56F4 (Data Row Visibility) | \u57FA\u7840\u6570\u636E\u64CD\u4F5C\u6743 |\\n| :--- | :--- | :--- | :--- |\\n| \u4E13\u5458 | \u3010\u5F85\u529E\u4EFB\u52A1\u3011\u9875\u9762 | \u4EC5\u53EF\u89C1\u3010\u6307\u6D3E\u4EBA = \u5F53\u524D\u7528\u6237 ID\u3011\u7684\u4EFB\u52A1\u5355\u636E | \u67E5\u3001\u6539\u3001\u6D41\u8F6C |\\n| \u90E8\u95E8\u4E3B\u7BA1 | \u3010\u5168\u76D8\u76D1\u63A7\u3011\u9875\u9762 | \u53EF\u89C1\u3010\u5F52\u5C5E\u90E8\u95E8 = \u5F53\u524D\u90E8\u95E8\u3011\u7684\u6240\u6709\u72B6\u6001\u5355\u636E | \u67E5\u3001\u91CD\u65B0\u5206\u914D\u3001\u5BA1\u6279 |","owner":"wansgenhao","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-06-02T07:27:14.814Z"}')}}]);